const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const P=(slug,name,group,problem,solution,status,tags,use,limits,code,flow,evidence,repo)=>({slug,name,group,problem,solution,status,license:'MIT',language:'C99',platform:'Portable C99; integration depends on caller-provided adapters',tags,use,limits,code,flow,evidence,repo:repo||`https://github.com/Vanderhell/${slug}`});
const projects=[
P('loxdb','LOX DB','LOX','Predictable persistent data on constrained firmware.','One API over key-value, time-series and small fixed-schema relational engines, with optional storage HAL persistence and WAL recovery.','v1.5.1 release line',['bounded allocation','WAL','deterministic','embedded'],['Store configuration or binary state by key','Keep typed telemetry streams with retention policies','Use small indexed fixed-schema tables','Recover a storage-backed database after an interrupted write'],['Not a SQL database or multi-process server','No unbounded queries, transparent large-object storage or advanced indexing','The core allocation guarantee excludes ports and user callbacks'],`#include "lox.h"\n#include "lox_port_ram.h"\n\nlox_t db; lox_storage_t storage;\nlox_cfg_t cfg = {0};\nif (lox_port_ram_init(&storage, 64u * 1024u) != LOX_OK) return 1;\ncfg.storage = &storage; cfg.ram_kb = 32u;\nif (lox_init(&db, &cfg) != LOX_OK) return 1;\nuint8_t value = 7u;\nif (lox_kv_put(&db, "k", &value, sizeof value) != LOX_OK) return 1;\n/* Expected: LOX_OK; key k contains one byte with value 7. */`,`Application → LOX DB → KV / TS / REL → WAL → storage HAL`,['571 microtest cases across 61 C test files plus one C++ wrapper test are documented in docs/TEST_SUITE_SIZE.md','Evidence matrix separates source-visible, host-tested and hardware claims','ESP32-S3 published measurements use an in-RAM flash-like backend, not physical NOR or brownout testing']),
P('loxbudget','LOX Budget','LOX','Risky operations start while RAM, queue, energy or write budgets are already under pressure.','A caller-owned admission controller returns an explicit allow, degrade, defer or deny decision before work starts.','v1.0.1 tagged snapshot; development line Unreleased',['no-heap','deterministic','single-header','embedded'],['Gate an OTA attempt on energy and flash budget','Degrade logging under memory pressure','Prevent MQTT bursts from exhausting queue slots','Enforce flash-write lifetime budgets'],['Not a scheduler, allocator, watchdog, logger or RTOS replacement','Policies and resource measurements are supplied by the application','The repository makes no safety-certification claim'],`#include "loxbudget.h"\nstatic uint32_t mem[(LOXBUDGET_REQUIRED_SIZE(2,2,0)+3u)/4u];\nloxbudget_t b; loxbudget_decision_t d;\nloxbudget_op_profile_t p=loxbudget_op_profile_default(0);\nif (loxbudget_init_simple(&b,mem,sizeof mem,2,2)!=LOXBUDGET_OK) return 1;\n(void)loxbudget_set_resource(&b,0,10,LOXBUDGET_RES_REUSABLE);\n(void)loxbudget_register_op(&b,&p);\n(void)loxbudget_op_set_need(&b,0,0,5);\n(void)loxbudget_check(&b,0,&d);\n/* Expected: d.action == LOXBUDGET_ALLOW_FULL. */`,`Application → resource snapshot → LOX Budget policy → decision`,['GCC and Clang host CI, Cortex-M0 cross-build, ASan/UBSan and fuzz smoke are listed in the repository verification table','Tests and optional audit trail cover decision paths']),
P('loxseq','LOX Sequence','LOX','A multi-step operation loses its safe recovery position after reset or power loss.','A heap-free step sequencer writes CRC-protected checkpoints and computes a conservative recovery verdict on boot.','Current documented development',['no-heap','power-loss recovery','deterministic','embedded'],['Resume a staged service procedure after reboot','Restart a non-resumable step from its beginning','Require operator action for an ambiguous checkpoint','Route corrupt or unsupported checkpoints to safe initialization'],['Not a recipe manager, graph FSM or safety library','One sequence runs per instance','Boot-local elapsed time is not restored across reboot','Storage durability is the caller backend’s responsibility'],`#include "loxseq/loxseq.h"\nloxseq_t seq;\nloxseq_init(&seq, steps, STEP_COUNT, &storage);\nloxseq_recovery_verdict_t v=loxseq_recover(&seq,reboot_reason);\nif(v==LOXSEQ_RECOVERY_RESUME) loxseq_start_resume(&seq,now_ms);\n/* Expected: recovery verdict selects an explicit start path. */`,`Boot → checkpoint read → recovery verdict → start policy → step`,['Unit tests cover CRC vectors, corruption fallbacks, resume/restart semantics, branching, timeouts and storage failures','Repository documents Ubuntu, Windows and macOS coverage plus ASan/UBSan on Ubuntu']),
P('loxperm','LOX Perm','LOX','Equipment actions need explainable permissives and interlocks instead of scattered booleans.','A header-only evaluator qualifies inputs, latches denials, records first-out state and supports controlled bypass metadata.','Current documented development',['header-only','no-heap','deterministic','embedded'],['Gate a pump start on multiple permissives','Latch a fault until an explicit reset','Debounce an interlock input','Record which condition denied first'],['Not a safety-certified interlock system','A shared chain requires external synchronization','Default condition mask is 32 entries; optional wide mode is 64'],`#include <loxperm/loxperm.h>\nloxperm_chain_t chain;\nloxperm_chain_init(&chain, defs, DEF_COUNT);\nloxperm_set(&chain, 0, true, now_ms);\nbool allowed=loxperm_is_permitted(&chain, now_ms);\n/* Expected: allowed and deny mask reflect qualified inputs. */`,`Inputs → qualification → latch / bypass policy → permission + diagnostics`,['Header-only and heap-free claims map to include/loxperm/loxperm.h','Tests cover snapshot validation and configuration contracts']),
P('loxalarm','LOX Alarm','LOX','Hand-written threshold alarms chatter, disappear before acknowledgement or lose operator state.','A deterministic alarm lifecycle adds delays, latching, acknowledge, shelving and portable snapshots to caller-supplied conditions.','Pre-1.0 work documented',['no-heap','deterministic','single-header','embedded'],['Delay activation of a noisy pressure condition','Latch an alarm until an operator acknowledges it','Shelve an alarm during bounded maintenance','Emit transition events to an external history system'],['Not safety-rated, an HMI, history database or transport','Does not calculate thresholds or signal filtering','Snapshot integrity and persistence must be provided externally','No first-out detection'],`#include "loxalarm/loxalarm.h"\nlox_alarm_t alarm;\nlox_alarm_config_t cfg={.on_delay_ms=2000,.latched=true};\nlox_alarm_init(&alarm,&cfg);\nlox_alarm_update(&alarm,pressure_high,now_ms);\nif(lox_alarm_just_activated(&alarm)) log_event("pressure");\n/* Expected: activation only after the configured delay. */`,`Condition → delay/latch policy → alarm state → transition event`,['Repository tests include deterministic invariant exercise and uint32_t clock-wrap coverage','Evidence and limitations are explicitly separated in docs']),
P('loxboot','LOX Boot','LOX','Firmware updates need validated slots, explicit handoff and rollback-oriented state.','A C99 bootloader core provides A/B state, UART update transport and adapter boundaries.','Current documented development',['no-heap','boot recovery','ESP32-S3','embedded'],['Receive an update over the supplied UART transport','Boot a pending image and require confirmation','Roll back an unconfirmed image on the next boot','Keep platform jump logic behind an adapter boundary'],['STM32 hardware is explicitly not verified','Board integration, flash layout and jump behavior remain platform work','It is a bootloader core, not an application-side crash-loop manager'],`#include "loxboot.h"\nloxboot_ctx_t boot;\n/* Configure storage and platform callbacks from the adapter contract. */\n/* Call the documented boot/update state machine from the platform entry. */\n/* Expected: an explicit selected slot or update state. */`,`Reset → validate boot state → select A/B slot → platform handoff`,['Host CMake and 20 CTest entries are documented as verified','ESP32-S3 ESP-IDF 5.5.1 build, flash, runtime and OTA/rollback runs are recorded in HARDWARE_EVIDENCE.md']),
P('loxdust','LOX Dust','LOX','Small persistent objects need a canonical layout and recovery checks without storing raw C structs.','A portable object store registers fixed objects, computes deterministic layout and exposes format, mount, propose, check and repair operations.','Current documented development',['persistent storage','caller-owned','deterministic','embedded'],['Persist a small configuration object','Validate object layout on mount','Check and repair redundant object state','Use host backends while developing an adapter'],['Not a general database or filesystem','Backend durability and power-loss behavior depend on the supplied backend','Object schema and storage sizing are fixed by the application'],`#include "loxdust/loxdust.h"\n/* Register objects and provide a storage backend as documented. */\n/* Format once, then mount and read/write registered objects. */\n/* Expected: explicit status from every storage operation. */`,`Application object → registered layout → check/repair → backend`,['Source includes tests and host-side backends','Repository documents canonical fixed-width encoding and caller-owned context']),
P('loxguard','LOX Guard','LOX','A parser or other risky block can fail without preserving useful diagnostic context.','Guard Blocks wrap documented host-tested execution paths, record evidence and route failures to configured policy actions.','Current documented development',['safe execution','diagnostics','policy','embedded'],['Wrap a checked parser operation','Capture failure evidence before policy handling','Exercise timeout behavior in the host demo path','Expose diagnostic state through the shell helper'],['Not a process sandbox or memory-safety proof','Host-only demo APIs are explicitly demo/test-only','Platform action hooks and policy are application responsibilities'],`#include "loxguard.h"\n/* Initialize a guard with caller policy and evidence storage. */\n/* Execute the checked block and inspect its explicit result. */\n/* Expected: success, or evidence plus a configured policy action. */`,`Risky code → Guard Block → evidence → policy action`,['Repository includes tests, examples and host-only checked-parser demos','Public and experimental surfaces are separated in docs/API.md']),
P('loxsort','LOX Sort','LOX','One fixed sorting algorithm cannot satisfy every stability, scratch and recursion constraint.','A stateless dispatcher selects among eligible C99 algorithms using explicit constraints and an offline profile.','Experimental',['deterministic','experimental','no-heap core','embedded'],['Sort small nearly ordered arrays with low overhead','Require stable ordering when scratch memory is available','Avoid recursion in a constrained build','Audit why a strategy was selected'],['Experimental; not presented as a universal performance winner','Stable merge requires a full scratch buffer','Profile quality depends on offline benchmark data'],`#include "loxsort/loxsort.h"\nlox_sort_options_t opt={0}; lox_sort_result_t result={0};\nopt.profile=&lox_profile_generic;\n(void)lox_sort(items,count,sizeof *items,int_compare,NULL,&opt,&result);\n/* Expected: sorted items and a reported selected strategy. */`,`Data constraints → dispatcher + profile → eligible algorithm → result`,['Tests cover API, algorithms, dispatch, profile logic and stability','A one-million-dataset release benchmark is documented, including non-optimal aggregate views']),
];

const micro=[
P('microfsm','microfsm','Micro-toolkit','Ad-hoc switch statements make state transitions hard to inspect.','A table-driven finite-state-machine engine keeps states, events and actions explicit.','Documented toolkit core',['no-heap','deterministic','state machine'],['Model a device operating mode','Centralize guarded transitions','Test transitions without hardware'],['Application owns concurrency and side effects'],`#include "mfsm.h"\n/* Define the documented transition table, initialize, then dispatch an event. */`,`Event → transition table → action → next state`,['Toolkit integration matrix maps the public header mfsm.h']),
P('microres','microres','Micro-toolkit','Transient failures need bounded retry and overload control.','Caller-owned retry, circuit-breaker and token-bucket primitives provide explicit resilience policy.','Audited contract rewrite; not declared release-ready',['no-heap','retry','rate limit'],['Retry a synchronous peripheral operation','Open a circuit after repeated failure','Rate-limit discrete work'],['No async scheduler, persistence, implicit thread safety or ISR-safe retry'],`#include "mres.h"\n/* Initialize a retry policy and call mres_retry_exec with clock/wait hooks. */`,`Operation → retry / breaker / limiter policy → result`,['C99 API and consumer fixtures are present']),
P('microconf','microconf','Micro-toolkit','Embedded configuration needs validation and corruption-aware persistence.','Validated schemas and a canonical two-slot format keep data caller-owned and bounded.','Under repair and verification',['no-heap','configuration','two-slot storage'],['Validate a fixed device configuration','Load defaults with explicit sizes','Persist configuration in two slots'],['No automatic schema migration','CRC32 detects corruption, not authentication','Some verification is explicitly pending'],`#include "mconf.h"\n/* Define a schema, caller-owned data, then initialize mconf_t. */`,`Schema + defaults → validation → canonical two-slot storage`,['Documentation marks verified and NOT VERIFIED areas']),
P('microlog','microlog','Micro-toolkit','Firmware needs bounded diagnostics without a general logging stack.','A small logging component routes structured records through caller-controlled storage and sinks.','Documented toolkit core',['logging','caller-owned','embedded'],['Record control-loop diagnostics','Route logs to a platform sink','Keep bounded history'],['Sink timing and synchronization are caller concerns'],`#include "mlog.h"\n/* Initialize caller-owned logger storage and emit a documented record. */`,`Event → log record → caller sink`,['Toolkit integration example uses the inspected public header mlog.h']),
P('microsh','microsh','Micro-toolkit','Embedded devices need a small command console over an existing byte stream.','A fixed-capacity shell parses ASCII commands and calls registered argc/argv handlers.','Current documented development',['no-heap','shell','UART'],['Add a UART service console','Expose status and diagnostic commands','Drive the shell from an RTT or USB CDC stream'],['ASCII-oriented; no Unicode line editing','msh_feed is not ISR-safe or reentrant','Output callbacks are synchronous'],`#include "msh.h"\nstatic msh_t shell;\nmsh_init(&shell,uart_print,NULL);\nmsh_register(&shell,"status","Show status",cmd_status);\nmsh_prompt(&shell);\n/* Expected terminal: prompt; status prints ok. */`,`Byte stream → line editor → command table → handler → output callback`,['CMake package and C/C++ consumer examples are documented']),
P('microcbor','microcbor','Micro-toolkit','Text payloads waste bytes and parsing work on constrained links.','A zero-allocation encoder/decoder implements a definite-length RFC 8949 subset.','Current documented development',['no-heap','CBOR','zero-copy decode'],['Encode compact telemetry maps','Decode known typed fields','Skip unknown fields for forward compatibility'],['No 64-bit integers, indefinite items or tags','Implements a subset, not all RFC 8949 features'],`#include "mcbor.h"\nuint8_t buf[64]; mcbor_enc_t e; size_t used=0;\nmcbor_enc_init(&e,buf,sizeof buf);\nmcbor_enc_map(&e,1); mcbor_enc_str(&e,"ok"); mcbor_enc_bool(&e,true);\nmcbor_enc_size(&e,&used);\n/* Expected: used reports a compact definite-length CBOR map. */`,`Values → caller buffer encoder → CBOR bytes`,['README documents zero allocation and the exact implemented subset']),
P('micoring','micoring','Micro-toolkit','Producer and consumer code need a bounded queue with explicit ownership.','A fixed-capacity copy-based ring uses caller-owned storage, with optional constrained SPSC atomic mode.','Current documented development',['no-heap','ring buffer','SPSC optional'],['Buffer fixed-size samples','Queue bytes between serialized tasks','Use one-producer/one-consumer atomic mode where supported'],['Default is single-context','Overwrite is unsupported in atomic mode','Snapshot queries need quiescence or synchronization in atomic mode'],`#include "mring.h"\nstatic uint8_t storage[8*sizeof(sample_t)]; mring_t ring;\nint rc=mring_init(&ring,storage,sizeof storage,8,sizeof(sample_t));\n/* Expected: rc indicates a ready eight-element ring. */`,`Producer → copy into ring → consumer copy out`,['CMake, Make and public contract documentation are present']),
P('microtimer','microtimer','Micro-toolkit','Main loops need bounded software timers without allocation or a scheduler.','A fixed-capacity manager fires caller callbacks from explicit tick calls.','Current documented development',['no-heap','timers','main loop'],['Blink an LED periodically','Schedule a one-shot timeout','Drive timers from a uint32 millisecond clock'],['No hidden locks or persistence','At most one fire per timer per tick; missed intervals are skipped','Shared access needs external synchronization'],`#include "mtimer.h"\nmtimer_t tm; mtimer_init(&tm,app_clock_ms);\nint id=mtimer_create(&tm,"blink",500,MTIMER_PERIODIC,blink_cb,&flag);\nmtimer_start(&tm,(uint8_t)id); mtimer_tick(&tm);\n/* Expected: callback runs when the deadline is due. */`,`Clock + timer table → tick → due callback`,['GCC, Clang, MSVC and ARM compile-only support scope is documented']),
P('microbus','microbus','Micro-toolkit','Firmware modules need bounded event delivery without hidden allocation.','A small event bus copies payload bytes and supports synchronous publish or bounded deferred dispatch.','Current documented development',['no-heap','event bus','SPSC optional'],['Publish a sensor update synchronously','Queue deferred events for the main loop','Subscribe one handler to a topic'],['Default is single-context','General thread safety is not provided','Payload capacity and queue depth are compile-time bounded'],`#include "mbus.h"\nmbus_t bus; uint16_t mv=3300;\nmbus_init(&bus,NULL);\nmbus_subscribe(&bus,MBUS_TOPIC_SENSOR,on_sensor,NULL);\nmbus_publish(&bus,MBUS_TOPIC_SENSOR,&mv,sizeof mv);\n/* Expected: on_sensor receives a copied two-byte payload. */`,`Publisher → copied event → subscriber / deferred queue`,['Tests and configuration contracts are documented in the repository']),
];
