const loxFamilyPage=()=>`${head('LOX Family — Deterministic embedded building blocks','Explore the LOX product family by storage, execution, recovery, diagnostics and utilities.','lox-family.html')}<body data-project="lox-family">${nav('','lox-family')}<main id="main"><section class="hero family-hero"><div class="wrap"><div class="kicker">The LOX product family</div><h1>Embedded building blocks<br>for deterministic firmware.</h1><p>Choose a capability. See the failure it handles, then open the product built around that responsibility.</p></div></section><section class="section family-categories"><div class="wrap">${familyGroups.map(([name,desc,slugs],i)=>`<details ${i===0?'open':''}><summary><span>0${i+1}</span><div><h2>${name}</h2><p>${desc}</p></div><b>Explore</b></summary><div class="family-products">${slugs.map(slug=>{const p=projects.find(x=>x.slug===slug);return p?`<a href="projects/${p.slug}.html"><span>${publicStatus(p.status)}</span><h3>${p.name}</h3><p>${p.problem}</p><em>Open product →</em></a>`:''}).join('')}</div></details>`).join('')}</div></section><section class="section experience-lab"><div class="wrap"><div class="kicker">Experience the responsibility</div><h2>Not feature lists. System outcomes.</h2><div class="experience-grid">${experienceSvg('LOX Budget',['Resources','Decision','Allow / Defer'])}${experienceSvg('LOX Guard',['Fault','Evidence','Policy'])}${experienceSvg('LOX DB',['Write','Power loss','Recovery'])}</div></div></section></main>${footer('')}</body></html>`;
