const toolkitLanding=()=>`${head('Micro Toolkit — Small portable independent C libraries','Choose small independent C components for observation, control, storage, timing and encoding.','micro-toolkit.html')}<body data-project="micro-toolkit">${nav('','micro-toolkit')}<main id="main"><section class="hero toolkit-hero"><div class="wrap"><p class="toolkit-word">Small.<br>Portable.<br>Independent.</p><h1>Micro Toolkit</h1><p>Take one component. Keep ownership. Bring no framework.</p></div></section><section class="section toolkit-picker"><div class="wrap"><div class="kicker">Choose by responsibility</div>${toolkitGroups.map(([name,slugs])=>`<details><summary><h2>${name}</h2><span>${slugs.length} ${slugs.length===1?'component':'components'} +</span></summary><div class="toolkit-items">${slugs.map(slug=>{const p=projects.find(x=>x.slug===slug);return `<a href="projects/${p.slug}.html"><b>${p.name}</b><span>${p.problem}</span><em>View →</em></a>`}).join('')}</div></details>`).join('')}</div></section></main>${footer('')}</body></html>`;
const aboutPage=()=>`${head('About Vanderhell — Embedded systems development','About Vanderhell, the engineering focus behind LOX and the independent embedded systems portfolio.','about.html')}<body data-project="about">${nav('','about')}<main id="main"><section class="hero about-hero"><div class="wrap"><div class="kicker">About Vanderhell</div><h1>I build small systems software with explicit boundaries.</h1><p>My work focuses on native C libraries for persistent state, recovery, diagnostics, communication and predictable resource use.</p></div></section><section class="section"><div class="wrap about-layout"><div><h2>Engineering over theatre.</h2><p class="lede">A library is useful when its ownership, failure modes and integration contract are as clear as its happy path.</p></div><div class="why-list"><div><b>01</b><span><strong>Bounded behavior</strong><small>Memory and runtime responsibilities stay visible.</small></span></div><div><b>02</b><span><strong>Recovery first</strong><small>Resets and interrupted work are normal system states.</small></span></div><div><b>03</b><span><strong>Evidence</strong><small>Claims map to APIs, examples, tests and recorded validation.</small></span></div></div></div></section><section class="section dark home-contact"><div class="wrap"><h2>Let’s talk about dependable embedded software.</h2><div class="actions"><a class="button primary" href="mailto:Vanderhell@gmail.com">Vanderhell@gmail.com</a><a class="button secondary" href="https://github.com/Vanderhell">GitHub</a></div></div></section></main>${footer('')}</body></html>`;
const problemMap=()=>`<section class="section problem-map-section" id="problems"><div class="wrap"><div class="kicker">Start with the failure you need to prevent</div><h2>What must your system handle?</h2><p class="lede">Choose a concrete engineering problem. The result explains which LOX projects address it and what responsibility each one takes; connections do not imply runtime dependencies.</p><div class="problem-map" data-problem-map><svg class="map-lines" viewBox="0 0 1000 650" preserveAspectRatio="none" aria-hidden="true"><g><path d="M500 325L500 72"/><path d="M500 325L180 170"/><path d="M500 325L820 170"/><path d="M500 325L120 325"/><path d="M500 325L880 325"/><path d="M500 325L180 500"/><path d="M500 325L820 500"/><path d="M500 325L500 590"/></g></svg><div class="map-core" aria-label="LOX project family"><strong>LOX</strong><span>Choose by system problem</span></div>${[
['diagnostics','Must an alarm remain actionable?','Delay, latch, acknowledge and evidence'],['storage','Must data survive a restart?','Bounded databases and persistent objects'],['boot','Must an update fail safely?','Validate slots, confirm or roll back'],['execution','Did risky code fail without context?','Capture evidence before policy action'],['admission','Can this operation start safely?','Allow, degrade, defer or deny'],['recovery','Must work resume after power loss?','Recover data, objects and procedures'],['processing','Must sorting obey hard constraints?','Stability, scratch and recursion limits'],['permissions','May this action run right now?','Qualify interlocks and explain denial']
].map(([id,title,sub],i)=>`<button class="map-node map-node-${i+1}" type="button" data-map-target="${id}" aria-expanded="false" aria-controls="map-panel-${id}"><strong>${title}</strong><span>${sub}</span></button>`).join('')}</div><div class="map-panels" aria-live="polite">${[
['diagnostics','An alarm must remain visible, actionable and explainable',[['LOX Alarm','loxalarm','Owns alarm delays, latching, acknowledge and shelving state.'],['LOX Guard','loxguard','Preserves failure evidence and requests a configured policy action.']]],
['storage','Configuration, telemetry or objects must survive a restart',[['LOX DB','loxdb','Stores key-value state, telemetry streams and small fixed-schema tables.'],['LOX Dust','loxdust','Stores registered objects with deterministic layout, checking and repair.']]],
['boot','A firmware update must not strand the device',[['LOX Boot','loxboot','Validates A/B slot state, hands off to the selected image and supports confirmation-oriented rollback flow.']]],
['execution','Risky code failed and diagnostic context must not disappear',[['LOX Guard','loxguard','Wraps documented risky paths, records evidence and routes the result to policy.']]],
['admission','Expensive work must not begin while resources are unsafe',[['LOX Budget','loxbudget','Checks RAM, queue, energy or write budgets before work and returns allow, degrade, defer or deny.']]],
['recovery','State or a multi-step operation must recover after power loss',[['LOX DB','loxdb','Replays WAL-backed database state when persistent mode is enabled.'],['LOX Dust','loxdust','Checks and repairs registered persistent objects.'],['LOX Sequence','loxseq','Reads a checkpoint and computes a conservative resume, restart or safe-init verdict.'],['LOX Boot','loxboot','Keeps pending-image confirmation and rollback-oriented boot state explicit.']]],
['processing','Sorting must respect stability, memory and recursion limits',[['LOX Sort','loxsort','Selects an eligible algorithm from the supplied constraints and offline profile.']]],
['permissions','An action may run only when every required condition permits it',[['LOX Perm','loxperm','Qualifies inputs, latches denials and reports deny masks and first-out state.']]]
].map(([id,title,items])=>`<section class="map-panel" id="map-panel-${id}" data-map-panel="${id}"><div><span class="kicker">Selected problem</span><h3>${title}</h3></div><div class="map-solutions">${items.map(([name,slug,text])=>`<a href="projects/${slug}.html"><strong>${name}</strong><span>${text}</span><em>Open project →</em></a>`).join('')}</div></section>`).join('')}</div></div></section>`;
const index=`${head('LOX — Liquid Oxygen for Embedded Systems','Native C libraries for persistent storage, recovery, diagnostics, resource admission and other constrained-system problems.','index.html')}<body data-project="home">${nav('','home')}<main id="main"><section class="hero"><div class="wrap"><div class="kicker">LOX</div><h1>Liquid Oxygen<br>for Embedded Systems</h1><p class="slogan">Focused native C libraries for constrained systems.</p><p>LOX is a family of independent libraries for persistent data, power-loss recovery, safe execution, diagnostics, resource admission and deterministic control. Pick the component that matches the problem; no shared runtime is implied.</p><div class="actions"><a class="button primary" href="#projects">Explore projects</a><a class="button secondary" data-event="github_click" href="https://github.com/Vanderhell">GitHub</a><a class="button secondary" data-event="docs_open" href="projects/loxdb.html#quick-start">Start with LOX DB</a></div></div></section><section class="section" id="problems"><div class="wrap"><div class="kicker">Find the right component</div><h2>What problem are you solving?</h2><div class="problem-grid">${[['Persistent storage','loxdb'],['Power-loss recovery','loxseq'],['Safe execution','loxguard'],['Runtime diagnostics','loxalarm'],['Resource admission','loxbudget'],['Permissions and interlocks','loxperm'],['Deterministic processing','loxsort'],['Boot and update recovery','loxboot'],['Embedded utilities','toolkit'],['Communication and networking','other']].map(([a,b])=>`<a class="problem" href="#${b}"><strong>${a}</strong><small>Open the matching product or group →</small></a>`).join('')}</div></div></section><section class="section alt" id="loxdb"><div class="wrap"><div class="kicker">Flagship open-source core</div><h2>LOX DB</h2><div class="flagship"><div><p class="lede">Predictable-memory embedded storage when configuration, telemetry and small structured tables need one bounded C99 core.</p><div class="badges"><span class="badge">MIT core</span><span class="badge">v1.5.1 line</span><span class="badge">KV · TS · REL</span></div><ul><li>One main core allocation after successful initialization; no allocator churn in normal core operations.</li><li>Optional persistence through a storage HAL, with WAL and recovery when enabled.</li><li>571 microtest cases are documented in the current local test-suite evidence file.</li></ul><div class="actions"><a class="button primary" href="projects/loxdb.html">Product detail</a><a class="button" data-event="quickstart_click" href="projects/loxdb.html#quick-start">Quick Start</a><a class="button" data-event="github_click" href="https://github.com/Vanderhell/loxdb">Repository</a></div></div><div class="visual"><h3>Three bounded storage models</h3><div class="flow"><span>Application</span> → <span>KV / TS / REL</span> → <span>WAL</span> → <span>Storage HAL</span></div><p>Use it when predictable integration matters more than SQL flexibility.</p><hr><h3>LOX DB Pro</h3><p>Commercial modules around the MIT LOX DB core: facade, safety/security, observability, lifecycle policies, connectivity and optional backends. Public integration docs are available; pricing is not published here.</p><a class="button secondary" data-event="commercial_licensing" href="projects/loxdb-pro.html">Commercial overview</a></div></div></div></section><section class="section" id="projects"><div class="wrap"><div class="kicker">Product finder</div><h2>The LOX family</h2><p class="lede">A shared product philosophy—small integration surfaces, explicit contracts and evidence—without claiming that every library shares one runtime.</p><div class="filters"><label>Search<input id="project-search" type="search" placeholder="Name, problem, use or tag"></label><label>Status<select data-filter="status"><option value="">All</option><option value="active">Documented</option><option value="experimental">Experimental</option></select></label><label>License<select data-filter="license"><option value="">All</option><option value="mit">MIT</option></select></label><label>Language<select data-filter="language"><option value="">All</option><option value="c99">C99</option></select></label></div><div class="cards">${cards(projects.filter(p=>p.group==='LOX'))}</div><p class="empty">No projects match these filters.</p></div></section><section class="section alt" id="toolkit"><div class="wrap"><div class="kicker">Independent building blocks</div><h2>Micro-toolkit</h2><p class="lede">Pick what you need, ignore the rest. The toolkit repository documents integration for nine independent upstream libraries; it does not vendor or pin them automatically.</p>${[['Observe and debug',['microlog','microsh']],['Control execution',['microfsm','microres','microtimer']],['Store and configure',['microconf','micoring']],['Encode and communicate',['microcbor','microbus']]].map(([g,s])=>`<div class="group"><h3>${g}</h3><div class="cards">${cards(projects.filter(p=>s.includes(p.slug)))}</div></div>`).join('')}<div class="actions"><a class="button" href="projects/micro-toolkit.html">Toolkit integration detail</a></div></div></section><section class="section" id="other"><div class="wrap"><div class="kicker">Independent technologies</div><h2>Beyond LOX</h2><p class="lede">Networking, boot history, flash abstraction, diagnostics, testing and narrowly scoped primitives maintained as separate projects.</p><div class="cards">${cards(projects.filter(p=>p.group==='Beyond LOX'))}</div></div></section><section class="section dark" id="about"><div class="wrap"><div class="kicker">About Vanderhell</div><h2>Technical work with explicit boundaries.</h2><p class="lede">This portfolio is derived from public APIs, documentation, examples, tests, build files and evidence notes in the local repositories. Unsupported claims and THENG internals are intentionally excluded.</p><div class="actions"><a class="button secondary" href="mailto:Vanderhell@gmail.com">Contact</a><a class="button secondary" data-event="github_click" href="https://github.com/Vanderhell">GitHub</a></div></div></section></main>${footer('')}</body></html>`;
