const buildOverrides={
  loxdb:`cmake --preset ci-debug-linux\ncmake --build --preset ci-debug-linux\nctest --preset ci-debug-linux --output-on-failure`,
  loxboot:`cmake -S . -B build -DLOXBOOT_BUILD_TESTS=ON -DLOXBOOT_BUILD_EXAMPLES=ON\ncmake --build build --config Release\nctest --test-dir build -C Release --output-on-failure`,
  'micro-toolkit':`cmake -S . -B build -DMICRO_TOOLKIT_BUILD_EXAMPLES=ON\ncmake --build build --config Release`,
  'ironfamily-fileengine':`cmake -S native -B native/build\ncmake --build native/build --config Release\nctest --test-dir native/build -C Release --output-on-failure`,
  'loxdb-pro':`# Build commands are supplied with the licensed package.\n# Public documentation does not contain the proprietary sources.`,
  loxc:`# No build is shown: auditable local public source was unavailable.`
};
function buildFor(p){return buildOverrides[p.slug]||`cmake -S . -B build\ncmake --build build --config Release\nctest --test-dir build -C Release --output-on-failure`;}
function flowStages(p){return p.flow.split('→').map((x,i)=>`<span><b>${String(i+1).padStart(2,'0')}</b>${esc(x.trim())}</span>`).join('<i aria-hidden="true">→</i>');}
function demo(p){const diagram=`<div class="flow" aria-label="Documented processing flow">${flowStages(p)}</div><p class="diagram-caption">${esc(p.solution)}</p>`;if(!['loxbudget','loxdb','loxseq','loxsort','loxguard'].includes(p.slug))return `<div class="demo"><span class="demo-label">Documented library flow</span>${diagram}</div>`;const controls=p.slug==='loxbudget'?`<label>Pressure <input type="range" min="0" max="100" value="35"></label>`:p.slug==='loxdb'?`<label>Operation <select><option value="commit">Complete write</option><option value="interrupt">Interrupt write</option></select></label>`:p.slug==='loxsort'?`<label><input type="checkbox"> Stable result required</label>`:'';return `<div class="demo" data-demo="${p.slug}"><span class="demo-label">Interactive concept demo based on documented behavior</span>${diagram}<div class="demo-controls">${controls}<button type="button" data-run-demo>Run flow</button></div><div class="demo-output" aria-live="polite">Choose an input and run the flow. This presentation models documented decisions; it does not execute the C library.</div></div>`}
function page(p){const desc=`${p.name}: ${p.problem} ${p.solution}`;return `${head(`${p.name} — Vanderhell portfolio`,desc,`projects/${p.slug}.html`,'../')}<body data-project="${p.slug}">${nav('../',p.slug)}<main id="main"><header class="hero product-hero"><div class="wrap"><nav class="crumb" aria-label="Breadcrumb"><a href="../index.html">Home</a> → <a href="../index.html#${p.group==='LOX'?'lox':'other'}">${esc(p.group)}</a> → ${esc(p.name)}</nav><div class="kicker">${esc(p.group)}</div><h1>${esc(p.name)}</h1><p class="slogan">${esc(p.problem)}</p><p>${esc(p.solution)}</p><div class="badges">${badge(p)}${p.tags.map(x=>`<span class="badge">${esc(x)}</span>`).join('')}</div><div class="actions"><a class="button primary" data-event="github_click" href="${p.repo}">GitHub</a><a class="button secondary" data-event="quickstart_click" href="#quick-start">Quick Start</a><a class="button secondary" data-event="docs_open" href="${p.repo}#documentation">Documentation</a></div><dl class="meta"><div><dt>Status</dt><dd>${esc(p.status)}</dd></div><div><dt>License</dt><dd>${esc(p.license)}</dd></div><div><dt>Language</dt><dd>${esc(p.language)}</dd></div><div><dt>Platform scope</dt><dd>${esc(p.platform)}</dd></div></dl></div></header><section class="section"><div class="wrap content-grid"><article class="content"><h2>What it solves</h2><p>${esc(p.problem)}</p><p>${esc(p.solution)}</p><h2>How it works</h2>${demo(p)}<h2>Use it when</h2><div class="use-grid">${p.use.map(x=>`<div class="panel">${esc(x)}</div>`).join('')}</div><h2 id="quick-start">Quick Start</h2><p>This minimum pattern is adapted from the repository README or public-header examples. Comments state the expected behavior; no terminal output is fabricated.</p><div class="code-wrap"><pre><code>${esc(p.code)}</code></pre></div><h2>Real scenarios</h2>${p.use.slice(0,3).map((x,i)=>`<section class="panel"><h3>${['At startup','During operation','After a fault or reset'][i]}</h3><p><strong>Situation:</strong> ${esc(x)}. <strong>Approach:</strong> integrate ${esc(p.name)} at the documented decision boundary. <strong>Result:</strong> the application receives an explicit state or return code and remains responsible for the surrounding policy.</p></section>`).join('')}<h2>Engineering evidence</h2><ul>${p.evidence.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="notice">Evidence here describes repository contents or explicitly recorded runs. It does not turn configured CI, compile-only checks or simulations into hardware validation.</p><h2 id="limits">Known limits</h2><ul>${p.limits.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h2>Technical information</h2><details><summary>Public API and integration</summary><p>Start with the public header shown in Quick Start and the repository documentation. Check every return value; storage, clock, transport and policy callbacks remain caller responsibilities where applicable.</p></details><details><summary>Memory and concurrency</summary><p>${p.tags.includes('no-heap')?'The repository documents no heap use for the library core; state is caller-owned.':'Use the memory contract documented by this project.'} Shared-instance access is not claimed safe unless the repository explicitly provides a concurrency mode.</p></details><details><summary>Build and configuration</summary><p>The local repository provides its authoritative CMake/build configuration. Only supported integration paths shown there should be enabled.</p></details></article><aside class="side panel"><strong>On this page</strong><a href="#quick-start">Quick Start</a><a href="#limits">Known limits</a><a data-event="github_click" href="${p.repo}">Source repository ↗</a><hr><p><small>Source reviewed: README, docs, examples, tests, public headers, build files and license where locally available.</small></p></aside></div></section></main>${footer('../')}</body></html>`}
const scenarioOverrides={
  loxdb:[['Interrupted configuration write','A device starts committing a configuration record and loses power before the operation completes.','On reopen, LOX DB scans the WAL and restores the last committed database state.'],['Bounded telemetry storage','Firmware appends measurements while working inside a fixed memory budget.','The time-series engine stores the samples through the configured storage HAL without allocator churn in normal core operation.'],['Small structured dataset','An embedded application needs a fixed-schema table but cannot justify a general SQL engine.','The relational model validates the bounded schema and exposes the result through the same LOX DB API.']],
  loxbudget:[['OTA under resource pressure','The OTA manager sees low energy reserve and too few permitted flash writes.','LOX Budget returns DEFER, so the application postpones staging and checks again after conditions improve.'],['Telemetry burst','A batch upload would exceed the current RAM and queue allowance.','The controller returns ALLOW_DEGRADED and the caller selects its smaller transfer profile.'],['Unsafe maintenance task','A maintenance operation requests resources that exceed a hard configured limit.','LOX Budget returns DENY before the task allocates memory or starts writing.']],
  microsh:[['UART service session','A technician opens the device UART and enters status.','microsh parses argv, calls the registered status handler and writes diagnostics through the configured output callback.'],['Focused configuration command','A device needs one inspectable command for changing a bounded setting.','The registered handler validates its arguments and returns command-specific output without a hidden shell runtime.'],['Unknown command','A mistyped service command arrives over the byte stream.','The shell rejects the name through its documented command table instead of dispatching an unrelated handler.']],
  loxboot:[['Pending firmware image','An update has been written to the inactive slot and awaits its first boot.','LOX Boot validates state, selects the pending slot and leaves confirmation to the documented application flow.'],['Unconfirmed update','The new image resets before it confirms successful startup.','The next boot follows the rollback-oriented slot state instead of repeatedly trusting the pending image.'],['Platform handoff','The core has selected a valid image on the target board.','The platform adapter performs the board-specific jump while the portable core keeps policy state explicit.']],
  iotspool:[['MQTT link disappears','Telemetry is produced while the broker cannot be reached.','iotspool appends the message to persistent storage before delivery and keeps it pending.'],['Power loss with queued data','The device resets with unsent records in the spool.','After restart, the queue recovers valid pending records and resumes caller-driven delivery.'],['Acknowledged delivery','The transport confirms that a queued record reached its destination.','The spool advances durable queue state so the acknowledged item is not sent as new work again.']],
  panicdump:[['Cortex-M fault','A processor fault occurs before normal logging can preserve register context.','panicdump commits a fixed CRC-protected record in retained RAM.'],['Next boot diagnosis','Firmware restarts and finds a retained crash record.','The application validates and exports the dump for offline decoding before clearing it.'],['Corrupt retained memory','The retained region contains bytes that do not pass format or CRC checks.','The reader rejects the record instead of presenting corrupted context as a valid crash.']]
};
const scenarioActions={loxdb:['Records the write intent and preserves the last committed state in its WAL-backed flow.','Appends samples through the selected bounded time-series model.','Applies the configured fixed schema through the relational engine.'],loxbudget:['Evaluates energy and flash-write allowances before OTA work begins.','Compares the requested batch profile with RAM and queue budgets.','Rejects the request against the configured hard resource limit.'],microsh:['Matches status in the command table and passes parsed arguments to its handler.','Parses the line and invokes only the explicitly registered configuration handler.','Fails command lookup without calling an application handler.'],loxboot:['Validates persistent slot state and selects the pending image.','Reads the missing confirmation state and applies the rollback-oriented selection rule.','Returns the selected image to the platform handoff adapter.'],iotspool:['Persists the message before asking the transport to deliver it.','Mounts the queue and identifies valid records that remain pending.','Commits the acknowledged queue position through the configured backend.'],panicdump:['Copies the bounded fault context and commits its CRC-protected retained record.','Validates the retained format and exposes the record for export.','Checks format and CRC before exposing any diagnostic fields.']};
function scenarioBlock(p){const custom=scenarioOverrides[p.slug];const rows=custom||p.use.slice(0,3).map(s=>[s,s,`The documented flow reaches ${p.flow.split('→').at(-1).trim()}, while surrounding policy remains explicit in the application.`]);return `<h2>Real scenarios</h2><div class="scenario-stack">${rows.map(([title,situation,result],i)=>`<section class="scenario"><span class="scenario-no">${String(i+1).padStart(2,'0')}</span><h3>${esc(title)}</h3><div><p><b>Situation</b>${esc(situation)}</p><p><b>${esc(p.name)} does</b>${esc(custom?scenarioActions[p.slug][i]:p.solution)}</p><p><b>Observable result</b>${esc(result)}</p></div></section>`).join('')}</div><h2>Engineering evidence</h2>`}
function richDemo(p){if(p.slug==='loxbudget')return `<div class="demo resource-demo" data-resource-demo><span class="demo-label">Interactive admission decision</span><div class="resource-controls"><label>RAM pressure <output>42%</output><input data-resource="ram" type="range" min="0" max="100" value="42"></label><label>Energy reserve <output>68%</output><input data-resource="energy" type="range" min="0" max="100" value="68"></label><label>Flash budget <output>74%</output><input data-resource="flash" type="range" min="0" max="100" value="74"></label></div><div class="decision-panel" aria-live="polite"><span>Decision</span><strong>ALLOW_FULL</strong><small>All configured resource thresholds are safe.</small></div><p class="diagram-caption">Presentation model of documented decisions; it does not execute the C library.</p></div>`;if(p.slug==='loxdb')return `<div class="demo wal-demo" data-wal-demo><span class="demo-label">Interrupted-write recovery scenario</span><div class="wal-track"><span class="active">Write record</span><i>→</i><span>Interrupt commit</span><i>→</i><span>Reopen database</span><i>→</i><span>WAL replay</span><i>→</i><span>Record restored</span></div><div class="demo-controls"><button type="button" data-wal-run>Simulate interruption</button></div><div class="decision-panel" aria-live="polite"><span>Current state</span><strong>READY</strong><small>Start the scenario to follow the documented recovery flow.</small></div></div>`;return null}
function detailEnhance(html,p){const demo=richDemo(p);if(demo)html=html.replace(/<div class="demo" data-demo="[^"]+">.*?<\/div><\/div>(?=<h2>Use it when<\/h2>)/s,demo);html=html.replace(/<h2>Real scenarios<\/h2>.*?<h2>Engineering evidence<\/h2>/s,scenarioBlock(p));return html}

const codeOverrides={
  microfsm:`#include "mfsm.h"\n\nenum { ST_IDLE, ST_BUSY };\nenum { EV_START, EV_DONE };\nstatic const mfsm_state_t states[]={\n  MFSM_STATE(ST_IDLE, NULL, NULL),\n  MFSM_STATE(ST_BUSY, NULL, NULL)\n};\nstatic const mfsm_transition_t transitions[]={\n  MFSM_TRANSITION(ST_IDLE,EV_START,ST_BUSY,NULL,NULL),\n  MFSM_TRANSITION(ST_BUSY,EV_DONE,ST_IDLE,NULL,NULL)\n};\nstatic const mfsm_def_t def=MFSM_DEF(states,transitions);\nmfsm_t fsm;\nif(mfsm_validate(&def)!=MFSM_OK) return 1;\nmfsm_init(&fsm,&def,ST_IDLE,NULL);\nmfsm_dispatch(&fsm,EV_START,NULL);\n/* Expected: mfsm_current(&fsm) == ST_BUSY. */`,
  microres:`#include "mres.h"\n\nmres_platform_t platform={.now_ms=now_ms,.wait_ms=wait_ms};\nmres_retry_policy_t policy={.max_attempts=3,.base_delay_ms=10};\nmres_retry_t retry;\nmres_retry_init(&retry,&policy,&platform);\nmres_result_t result=mres_retry_exec(&retry,read_sensor,&sensor);\n/* Expected: explicit success or exhausted-retry result. */`,
  microota:`#include "mota.h"\n\nmota_t ota;\nif(mota_begin(&ota,&image)!=MOTA_OK) return 1;\nif(mota_write_chunk(&ota,0,chunk,sizeof chunk)!=MOTA_OK) return 1;\nif(mota_verify(&ota)!=MOTA_OK) return 1;\nif(mota_commit(&ota)!=MOTA_OK) return 1;\n/* Expected: commit is requested only after read-back verification. */`,
  microdh:`#include "mdh.h"\n\nuint8_t public_key[MDH_KEY_SIZE];\nuint8_t shared[MDH_KEY_SIZE];\nif(mdh_public_key(public_key,private_key)!=MDH_OK) return 1;\nif(mdh_shared_secret_checked(shared,private_key,peer_key)!=MDH_OK) return 1;\n/* Clear private material with the documented helper after use. */`,
  microwdt:`#include "mwdt.h"\n\nmwdt_t watchdog;\nmwdt_config_t cfg={0};\nmwdt_init(&watchdog,&cfg);\nint task=mwdt_register(&watchdog,"control",100);\nmwdt_kick(&watchdog,(uint8_t)task,now_ms);\nmwdt_check(&watchdog,now_ms);\n/* Expected: a missed deadline requests the configured action. */`,
  num8_lup:`#include "num8lora_sender.h"\n#include "num8lora_receiver.h"\n\nnum8lora_sender_t sender;\nnum8lora_receiver_t receiver;\nnum8lora_sender_init(&sender,&sender_cfg);\nnum8lora_receiver_init(&receiver,&receiver_cfg);\nnum8lora_sender_enqueue_add(&sender,12345678u);\n/* Exchange BEACON, DATA and ACK/NACK through the caller transport. */`
};
function codeFor(p){return codeOverrides[p.slug.replace('-','_')]||p.code;}
function quickStart(html,p){const replacement=`<h2 id="quick-start">Quick Start</h2><p>A repository-backed path from a clean checkout to the first observable result.</p><ol class="quick-steps"><li><h3>1. Build and verify</h3><p>Run these commands from the project root. Tests run when the checked-in CMake configuration registers them.</p><div class="code-wrap"><pre><code>${esc(buildFor(p))}</code></pre></div></li><li><h3>2. Minimal use</h3><p>Adapted from a public header, README or checked-in example; required platform callbacks remain application-owned.</p><div class="code-wrap"><pre><code>${esc(codeFor(p))}</code></pre></div></li><li><h3>3. What happens</h3><div class="quick-result">${flowStages(p)}</div><p>${esc(p.solution)}</p></li></ol><h2>Real scenarios</h2>`;return html.replace(/<h2 id="quick-start">Quick Start<\/h2>.*?<h2>Real scenarios<\/h2>/s,replacement)}
